import{_ as t,o as i,c as a,a4 as o}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"Activity Provenance States","description":"","frontmatter":{},"headers":[],"relativePath":"reference/44-activity-provenance-states.md","filePath":"reference/44-activity-provenance-states.md","lastUpdated":1788532705000}'),c={name:"reference/44-activity-provenance-states.md"};function r(n,e,s,d,l,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="activity-provenance-states" tabindex="-1">Activity Provenance States <a class="header-anchor" href="#activity-provenance-states" aria-label="Permalink to &quot;Activity Provenance States&quot;">​</a></h1><p>Every Muhurtam activity has exactly one machine-readable provenance disposition. The disposition describes the authority of the activity-specific profile; it does not certify the astronomical engine or shared scoring layers.</p><table tabindex="0"><thead><tr><th>Rule field</th><th>Required ledger state</th><th>Meaning</th></tr></thead><tbody><tr><td><code>source_claim</code></td><td><code>verified</code></td><td>Implemented activity criteria match the precisely located source within the recorded scope</td></tr><tr><td><code>audit_claim</code></td><td><code>contradicted</code></td><td>An inspected source exposes a rule or taxonomy conflict that remains visible pending an approval-gated correction</td></tr><tr><td><code>heuristic_claim</code></td><td><code>heuristic</code></td><td>The behavior is intentionally project-defined or source-neutral and makes no claim of classical authority</td></tr></tbody></table><p>The fields are mutually exclusive. <code>tools/check_activity_provenance.py</code> fails for unknown claims, wrong surfaces, wrong states, duplicate claims or an activity with no disposition. <code>tools/export_activity_rules.py</code> carries the same field into the browser contract, while <code>tool_find_muhurta</code> returns it in <code>activity_profile</code> for MCP consumers.</p><h2 id="the-neutral-any-selector" tabindex="-1">The neutral <code>any</code> selector <a class="header-anchor" href="#the-neutral-any-selector" aria-label="Permalink to &quot;The neutral `any` selector&quot;">​</a></h2><p><code>Anything auspicious</code> is the sole heuristic activity profile. It contributes no activity-specific admission rule or scoring preference. It is useful for exploring shared day and slot calculations, but it is not a classical election for an unspecified act. Once the user&#39;s purpose is known, the corresponding purpose-specific activity profile takes precedence.</p><h2 id="adding-an-activity" tabindex="-1">Adding an activity <a class="header-anchor" href="#adding-an-activity" aria-label="Permalink to &quot;Adding an activity&quot;">​</a></h2><ol><li>Give the activity exactly one of the three claim fields.</li><li>Add the corresponding ledger entry with scope, implementation and review metadata.</li><li>For <code>source_claim</code>, record an inspected edition and exact locator.</li><li>Export the browser rules and test both browser and MCP disclosure.</li><li>Run <code>python tools/check_activity_provenance.py</code> and the full project verifier before review.</li></ol>',8)])])}const v=t(c,[["render",r]]);export{u as __pageData,v as default};
